<script>
  /**
   * UI root. Left and top bar. Switches between search results, article and the front page.
   */

  "use strict";
  import { rul, Article as ArticleRul } from "./Ruleset";
  import {
    LinksPage,
    Tr,
    tr,
    favicon,
    divider,
    tableSections,
  } from "./Components";
  import Article from "./Article.svelte";
  import Compare from "./Compare.svelte";
  import DamageCalc from "./DamageCalc.svelte";
  import TechTree from "./TechTree.svelte";
  import Pax from "./Pax.svelte";
  import Notepad from "./Notepad.svelte";
  import CogAnimation from "./CogAnimation.svelte";
  import { afterUpdate, onMount, setContext } from "svelte";
  import {
    revealed,
    reveal,
    revealLock,
    loaded,
    linksPageSorted,
    loadingFile,
    markersLoaded,
    leftRightClickSwipe,
  } from "./store";
  import { isAncestorOf } from "./util";
  import Download from "./Download.svelte";
  import onSwipe from "./swipe";
  import { useCache, packedData } from "./load";

  /**@type {ArticleRul}*/
  let article = null;
  let found = null;
  let query = "";
  let currentSection = null;
  let activeOption;
  let ignoreNextAutoscroll = false;
  let id = "";
  let searchDelayHandle = null;
  let seeSide = true;
  let hugeFont = false;
  let allowHugeFont = true;
  let showDropdown = false;
  let showLanguagesDropdown = false;
  let tooltip;
  let searching = false;
  let saveLoaded = false;
  let sortArticles = false;
  let compareMode = false;
  /** Compare pane contents, in pane order. Two by default, up to four. */
  let compareIds = ["", ""];
  /** Pane to drop the cursor into when compare opens, or -1. */
  let compareAutofocus = -1;
  /** Damage calculator mode, and the enemy it is pointed at. */
  let damageMode = false;
  let techMode = false;
  let techTopic = "";
  let damageTarget = "";
  /** PAX, the personnel manager. */
  let paxMode = false;
  /**
   * Any of the full-width tool screens. They all hide the article sidebar - it
   * is position:fixed, and left rendered it draws over the tool's own left panel.
   */
  $: toolMode = compareMode || damageMode || techMode || paxMode;

  let isTouch = "ontouchstart" in window;
  let lang;
  let markers;

  setContext("main", { revealed: () => revealed });

  loaded.subscribe((done) => {
    if (done) {
      loadState();
      checkHash();
    }
  });

  let _linksPageSorted;
  linksPageSorted.subscribe((v) => {
    _linksPageSorted = v;
    saveState();
  });

  let lrcs;
  leftRightClickSwipe.subscribe((v) => {
    lrcs = v;
  });

  /**
   * Read off the DOM, not assumed.
   *
   * The page ships `light-css` with media="none", i.e. the dark main.css alone.
   * Hardcoding "light" here made the variable disagree with what was actually on
   * screen from the first frame - and since saveState() persists the variable,
   * the next load applied a light theme nobody asked for. That is why an
   * exported file came out lighter than the app it was exported from.
   */
  let theme = themeFromDom();

  function themeFromDom() {
    const el = typeof document != "undefined" && document.getElementById("light-css");
    if (!el) return "dark";
    return el.getAttribute("media") == "none" ? "dark" : "light";
  }

  function toggleTheme() {
    theme = theme == "light" ? "dark" : "light";
    applyTheme();
    saveState();
  }

  function applyTheme() {
    let lightCSS = document.getElementById("light-css");
    lightCSS.setAttribute("media", theme == "light" ? "" : "none");
  }

  function saveState() {
    if (!saveLoaded) return;
    localStorage.xpediaSettings = JSON.stringify({
      hugeFont,
      seeSide,
      lang,
      sortArticles,
      theme,
      linksPageSorted: _linksPageSorted,
    });
    clog("ss", localStorage.xpediaSettings);
  }

  export function loadState() {
    try {
      clog("ls", localStorage.xpediaSettings);
      let data = JSON.parse(localStorage.xpediaSettings);
      if (data && typeof data == "object") {
        hugeFont = data.hugeFont;
        seeSide = data.seeSide;
        sortArticles = data.sortArticles;
        theme = data.theme;
        linksPageSorted.set(data.linksPageSorted);
        selectLang(data.lang);
        applyTheme();
      }
    } catch (e) {
      console.warn(e);
    }
    saveLoaded = true;
  }

  /**
   *
   * @param {string} text
   * @param {string} substr
   */
  function contains(text, substr) {
    return text.toLowerCase().indexOf(substr) != -1;
  }

  function selectLang(n) {
    if (rul.selectLang(n)) lang = n;
    saveState();
    checkHash();
  }

  /**
   * Navigate by hash, and cope with already being there.
   *
   * Assigning the hash it already has fires no `hashchange`, so checkHash never
   * runs and the click does nothing at all. That is invisible until the flags
   * and the hash disagree - which they did when a mode flag was left set - and
   * then a button silently needs pressing twice. Calling checkHash directly
   * makes the hash the single source of truth either way.
   */
  function setHash(h) {
    if (window.location.hash == h) checkHash();
    else window.location.hash = h;
  }

  function goTo(id) {
    setHash("##" + id);
  }

  function goTech() {
    if (techMode) {
      goTo("HOME");
      return;
    }
    // Entering from a research article points the tree straight at it.
    setHash("##TECH" + (article && rul.research && rul.research[article.id] ? "::" + article.id : ""));
  }

  function goPax() {
    setHash(paxMode ? "##HOME" : "##PAX");
  }

  function goDamage() {
    if (damageMode) {
      goTo("HOME");
      return;
    }
    // Entering from a unit's article points the calculator straight at it.
    setHash("##DAMAGE" + (article && rul.units && rul.units[article.id] ? "::" + article.id : ""));
  }

  function compareHash() {
    return "##COMPARE::" + compareIds.join("::");
  }

  function goCompare() {
    if (compareMode) {
      // Leaving compare drops you back on whatever the focused pane was showing,
      // falling back to the first non-empty pane.
      let back = compareIds.filter((id) => id)[0];
      goTo(back || "HOME");
      return;
    }
    // Entering from an article prefills the first pane with it, so all you have
    // to do is search for the thing you want to compare it against.
    if (article) {
      compareIds = [article.id, ...compareIds.slice(1)];
      compareAutofocus = 1;
    } else {
      compareAutofocus = 0;
    }
    setHash(compareHash());
  }

  /** Open compare directly with `left` and `right` - used by shift-clicking a link. */
  function goCompareWith(left, right) {
    compareIds = [left || "", right || ""];
    compareAutofocus = -1;
    window.location.hash = compareHash();
  }

  function onCompareChange(e) {
    compareIds = e.detail;
    window.location.hash = compareHash();
  }

  let searchinInProgres;

  async function checkHash() {
    showDropdown = showLanguagesDropdown = false;
    let hash = decodeURI(document.location.hash);
    if (hash.substring(0, 2) != "##") return;
    id = hash.substring(2);

    // Compare mode: ##COMPARE::A::B[::C[::D]] (ids optional, two or more panes).
    // Handled before the generic "::" query split below.
    // Damage calculator: ##DAMAGE[::TARGET_ID]
    // Personnel manager: ##PAX
    if (id == "PAX") {
      paxMode = true;
      damageMode = false;
      compareMode = false;
      techMode = false;
      if (article) article = null;
      found = null;
      searching = false;
      return;
    }
    paxMode = false;

    if (id.substring(0, 6) == "DAMAGE") {
      damageMode = true;
      compareMode = false;
      // Every early-returning branch must clear the OTHER modes, or the render
      // order decides which screen you get rather than the hash.
      techMode = false;
      damageTarget = id.split("::")[1] || "";
      // Same guard as compare: article is a {#key} dependency, so leaving it
      // set would tear the component down on every hash write.
      if (article) article = null;
      found = null;
      searching = false;
      return;
    }
    // Tech tree: ##TECH[::TOPIC_ID]
    if (id.substring(0, 4) == "TECH") {
      techMode = true;
      damageMode = false;
      compareMode = false;
      techTopic = id.split("::")[1] || "";
      // Same guard as compare and damage: article is a {#key} dependency.
      if (article) article = null;
      found = null;
      searching = false;
      return;
    }
    techMode = false;
    damageMode = false;

    if (id.substring(0, 7) == "COMPARE") {
      compareMode = true;
      let parts = id.split("::").slice(1);
      while (parts.length < 2) parts.push("");
      compareIds = parts.slice(0, 4);
      // Guard so repeated compare hash updates don't invalidate `article`
      // (a key dependency) and tear down the Compare component, which would
      // wipe an in-progress search in the pane you're not changing.
      if (article) article = null;
      found = null;
      searching = false;
      return;
    }
    compareMode = false;

    if (id == "HOME") {
      query = "";
    }

    searching = false;

    if (id) {
      let dd = id.indexOf("::");
      if (dd != -1) {
        query = id.substring(dd + 2).toLowerCase();
        id = id.substring(0, dd);
      }

      if (id == "SEARCH") {
        searching = true;
        if (query.length >= 2) {
          searchinInProgres = true;
          found = await rul.search[rul.langName].findArticles(query);
          searchinInProgres = false;
        } else found = 0;
        article = null;
      } else {
        found = null;
        if (!article || article.id != id) article = rul.article(id);
      }
    }

    if (article) {
      if (article.sections) {
        if (!article.sections.includes(currentSection)) {
          currentSection = article.sections[0];
        }
      }
    }

    if (activeOption) {
      centerOnArticle();
    }
  }

  function centerOnArticle() {
    setTimeout(() => activeOption?.scrollIntoView({ block: "center" }), 50);
  }

  function nextArticle(delta) {
    if (lrcs) {
      lrcs(delta);
      return;
    }
    let nextArticle = rul.findNextArticle(
      article,
      delta,
      currentSection,
      sortArticles
    );
    if (nextArticle) {
      goTo(nextArticle.id);
    }
  }

  function searchKeyUp(e) {
    if (searchDelayHandle) clearTimeout(searchDelayHandle);

    searchDelayHandle = setTimeout(
      () => {
        goTo("SEARCH::" + e.target.value);
        searchDelayHandle = null;
      },
      e.key == "Enter" ? 10 : 1000
    );
  }

  window.onhashchange = checkHash;

  $: {
    //if (article) clog(article);
    document.documentElement.style.fontSize = hugeFont ? "24pt" : "12pt";
  }

  function dropdown(val = null) {
    if (val === null) {
      showDropdown = !showDropdown;
    } else {
      if (!isTouch) showDropdown = val;
    }
  }

  $: sortedArticles = (articles) =>
    sortArticles
      ? [...(articles || [])].sort((a, b) => (a.title > b.title ? 1 : -1))
      : articles;

  document.addEventListener("keydown", (event) => {
    // Compare owns its own arrow handling - it routes them to the focused pane.
    if (compareMode) return;
    // The calculator is a form; arrow keys belong to its number inputs.
    if (damageMode || paxMode) return;
    const keyName = event.key;
    if (keyName == "ArrowRight") nextArticle(1);
    if (keyName == "ArrowLeft") nextArticle(-1);
  });

  /**
   * Shift-click (or middle-click) any link to open it in compare against the
   * article you are currently reading. Makes compare something you fall into
   * mid-read rather than a mode you have to remember exists.
   */
  function compareFromLink(event) {
    if (compareMode) return; // panes handle their own shift-clicks
    let el = event.target;
    while (el && el.tagName != "A") el = el.parentNode;
    if (!el || el.tagName != "A") return;

    let href = el.getAttribute("href") || "";
    if (href.substring(0, 2) != "##") return;

    let target = decodeURI(href.substring(2));
    let dd = target.indexOf("::");
    if (dd != -1) target = target.substring(0, dd);
    if (!target || !rul.article(target)) return;

    event.preventDefault();
    event.stopPropagation();
    if (article && article.id != target) goCompareWith(article.id, target);
    else goCompareWith(target, "");
  }

  document.addEventListener(
    "click",
    (e) => {
      if (e.shiftKey && e.button == 0) compareFromLink(e);
    },
    true
  );
  document.addEventListener(
    "auxclick",
    (e) => {
      if (e.button == 1) compareFromLink(e);
    },
    true
  );

  /*onSwipe(document.body, (right) => {
    if (right) nextArticle(1);
    else nextArticle(-1);
  });*/

  /*document.body.addEventListener("touchstart", (e)=>{
    let tag = e.target.tag;
    if(tag != "A" && tag != "BUTTON" && e.changedTouches && e.changedTouches.length>0){
      let x = e.changedTouches[0].pageX;
      if(x<window.innerWidth/2)
        nextArticle(-1);
      else
      nextArticle(1);
    }    
  })*/

  window.addEventListener("mousemove", async (e) => {
    if (e.screenX < 10 && e.screenY < innerHeight / 3) {
      dropdown(true);
    } else {
      if (e.target && !isAncestorOf(navbarDropDown, e.target)) {
        dropdown(false);
      }
    }

    if (tooltip) {
      let el = e.target;
      while (el && el.attributes && !("tooltip" in el.attributes))
        el = el.parentNode;

      if (el && el.attributes && el.attributes.tooltip) {
        let idattr = el.attributes.tooltip;
        let rect = e.target.getBoundingClientRect();
        tooltip.style.left = rect.left + rect.width / 2 + "px";
        tooltip.style.top = (rect.top > 100 ? rect.top : rect.top + 120) + "px";
        let id = idattr.value;
        toggleTooltip(
          id in rul.lang && !e.shiftKey ? rul.lang[id] : id.substring(4)
        );
      } else {
        toggleTooltip(null);
      }
    }
  });

  function toggleTooltip(text) {
    tooltip.innerHTML = text;
    let classes = tooltip.classList;
    if (text) {
      classes.add("visible");
    } else {
      classes.remove("visible");
    }
  }

  let navbarDropDown;
</script>

<svelte:head>
  {#if !article}
    <title>{tr("XPedia")}</title>
  {/if}
  <meta charset="utf8" />
  <meta name="keywords" content="OpenXCom" />
  <link rel="icon" type="image/png" href={favicon} />
</svelte:head>

{#if !$loaded}
  <div style="opacity:0.3">{@html $loadingFile}</div>
  <div class="centered">
    <CogAnimation size={200} />
  </div>
{:else}
  {#key [lang, article, markersLoaded]}
    <nav class="navbar flex-horisontal">
      <!-- svelte-ignore a11y-mouse-events-have-key-events -->
      <div
        class="navbar-dropdown-container"
        bind:this={navbarDropDown}
        on:mousemove={(e) => {
          dropdown(true);
        }}
        on:mouseout={(e) => {
          if (e.target && !isAncestorOf(e.target)) {
            dropdown(false);
          }
        }}
      >
        <div
          class="navbar-button dropdown-button"
          on:click={(e) => {
            //dropdown();
            goTo("HOME");
            //e.stopPropagation();
          }}
        >
          <img src={favicon} alt="XPedia" class="xpedia-icon" />
          <nobr>
            <span class="on-wide">{rul.tr("XPedia")}&nbsp;</span>
            <span style="transform:scale(1.5,0.75); display:inline-block;">
              ˅
            </span>
          </nobr>
        </div>

        <div
          class="navbar-dropdown"
          style={showDropdown ? "visibility:visible" : "visibility:hidden"}
        >
          <div class="flex-horisontal">
            <div class="navbar-auto navbar-list">
              <a href="##HOME" style="text-decoration:underline;">
                <Tr s={"HOME"} />
              </a>
              <div style="height:0.5em;" />
              {#each rul.sectionsOrder as section, i}
                <a href={"##" + section.id}><Tr s={section.id} /></a>
              {/each}
            </div>
            <div class="navbar-custom navbar-list">
              {#each rul.sortedTypeSections() as section, i}
                <a href={"##" + section.id}
                  ><Tr s={section.id} />{tableSections.includes(section.id)
                    ? "☰"
                    : ""}</a
                >
              {/each}
            </div>
          </div>
        </div>
      </div>

      <!--
        <a
          class="navbar-button navbar-current-article"
          href={"##" + (currentSection ? currentSection.id : "HOME")}
        >
          {currentSection ? rul.tr(currentSection.id) : ""}
        </a>
      -->

      <!-- svelte-ignore a11y-mouse-events-have-key-events -->
      <div
        class="navbar-button {$revealed ? 'reveal-lock' : ''}"
        id="reveal"
        on:mouseover={(e) => {
          reveal(true);
        }}
        on:mouseout={(e) => {
          reveal(false);
        }}
        on:click={(e) => {
          revealLock();
          saveState();
        }}
        tooltip="tip_reveal"
      >
        👁
      </div>

      <div
        class="navbar-button {compareMode ? 'reveal-lock' : ''}"
        id="compare-button"
        title={compareMode
          ? "Leave compare"
          : "Compare (shift-click any link to compare against this page)"}
        on:click={goCompare}
      >
        <nobr>⇄<span class="on-wide">&nbsp;<Tr s="Compare" /></span></nobr>
      </div>

      <div
        class="navbar-button {damageMode ? 'reveal-lock' : ''}"
        id="damage-button"
        title={damageMode ? "Leave the damage calculator" : "Estimate damage against an enemy"}
        on:click={goDamage}
      >
        <!-- No icon, so the label carries the button on narrow layouts too -
             it is short enough not to need the on-wide hiding the others use. -->
        <nobr>CENTCOM</nobr>
      </div>

      <div
        class="navbar-button {techMode ? 'reveal-lock' : ''}"
        id="tech-button"
        title={techMode ? "Leave the tech tree" : "Browse the research tree against a save"}
        on:click={goTech}
      >
        <nobr>TECH</nobr>
      </div>

      <div
        class="navbar-button {paxMode ? 'reveal-lock' : ''}"
        id="pax-button"
        title={paxMode ? "Leave the personnel manager" : "Your whole crew on one screen: stats, roles, careers, squads"}
        on:click={goPax}
      >
        <nobr>PAX</nobr>
      </div>

      <Notepad />

      <div class="stretcher on-wide" />

      {#if !packedData}
        <button
          class="navbar-button"
          on:click={(e) => {
            useCache("wipe");
            location.reload();
          }}
          tooltip="tip_refresh"
        >
          ⭯
        </button>
      {/if}

      <button class="navbar-button" on:click={() => toggleTheme()}> ▀▄ </button>

      {#if allowHugeFont}
        <button class="navbar-button" on:click={(e) => (hugeFont = !hugeFont)}>
          <span style="font-size:150%">A</span>
          <span style="font-size:75%">A</span>
        </button>
      {/if}

      {#if rul.langNames?.length > 1}
        {#if rul.langNames?.length <= 3}
          {#each rul.langNames as lang}
            <button class="navbar-button" on:click={(e) => selectLang(lang)}>
              <nobr><Tr s={lang} /></nobr>
            </button>
          {/each}
        {:else}
          <!-- svelte-ignore a11y-mouse-events-have-key-events -->
          <div
            class="navbar-dropdown-container select-language"
            on:mouseover={(e) => !isTouch && (showLanguagesDropdown = true)}
            on:mouseout={(e) => !isTouch && (showLanguagesDropdown = false)}
          >
            <button
              class="navbar-button"
              on:mousedown={(e) =>
                (showLanguagesDropdown = !showLanguagesDropdown)}
            >
              <big><Tr s={rul.langName} /></big>
            </button>
            <div
              class="navbar-dropdown"
              style={showLanguagesDropdown
                ? "visibility:visible"
                : "visibility:hidden"}
            >
              {#each rul.langNames as lang}
                <div class="clickable" on:click={(e) => selectLang(lang)}>
                  <nobr><Tr s={lang} /></nobr>
                </div>
              {/each}
            </div>
          </div>
        {/if}
      {/if}

      <!--
    <select on:change={e=>{selectLang(e.target.value)}}>
      {#each rul.langNames as langName}
        <option selected={lang == langName} value={langName}>{rul.str(langName) || langName}</option>
      {/each}
    </select>-->

      <div class="navbar-search">
        <input
          class="input"
          type="text"
          id="search-string"
          bind:value={query}
          on:keyup={searchKeyUp}
          placeholder={tr("Search...")}
        />
      </div>
    </nav>

    <!-- techMode belongs in this list as much as compare and damage do: the
         article sidebar is position:fixed, so leaving it rendered draws the
         section's article list, its scrollbar and its A-Z button straight over
         the tech screen's own left panel. -->
    {#if seeSide && !toolMode}
      <nav class="sidebar">
        <button
          class="side-sort-button"
          style={sortArticles ? "" : "text-decoration:line-through"}
          on:click={(e) => {
            sortArticles = !sortArticles;
            centerOnArticle();
            saveState();
          }}
        >
          <Tr s="A-Z" />
        </button>

        <div class="menu-list">
          {#each sortedArticles(currentSection?.articles) || [] as option}
            {#if article && article.id == option.id}
              <a
                href={"##" + option.id}
                bind:this={activeOption}
                class="active-article-option side-link"
              >
                <Tr s={option.id} />
              </a>
            {:else}
              <a
                class="side-link"
                href={"##" + option.id}
                on:click={() => {
                  ignoreNextAutoscroll = true;
                }}
              >
                <Tr s={option.id} />
              </a>
            {/if}
          {/each}
        </div>
        <br />
      </nav>
    {/if}

    {#if !toolMode}
      <button
        class="side-hide-button"
        on:click={(e) => {
          if (e.button == 0) seeSide = !seeSide;
          saveState();
        }}
        style={seeSide ? "" : "left:1em;"}
      >
        <span style="font-size:150%">≡</span>
      </button>
    {/if}

    <div
      class="main"
      id="main"
      class:main-compare={toolMode}
      style={seeSide && !toolMode ? "" : "padding-left:1rem;"}
    >
      {#if paxMode}
        <Pax />
      {:else if techMode}
        <TechTree topicId={techTopic} />
      {:else if damageMode}
        <DamageCalc targetId={damageTarget} />
      {:else if compareMode}
        <Compare
          ids={compareIds}
          {sortArticles}
          autofocus={compareAutofocus}
          on:change={onCompareChange}
          on:open={(e) => goTo(e.detail)}
        />
      {:else if query && searching}
        Searching "
        <em>{query}</em>
        ":
        <br />
        {#key found}
          {#if found && found.length > 0}
            <LinksPage
              links={found
                .filter((a) => contains(rul.tr(a).toLowerCase(), query))
                .slice(0, 200)}
            /><br />
            <LinksPage
              links={found
                .filter((a) => !contains(rul.tr(a).toLowerCase(), query))
                .slice(0, 200)}
              title=" "
            />
          {:else if query.length < 2}
            <i>Query too short</i>
          {:else if searchDelayHandle || searchinInProgres}
            <Tr s="Initializing search engine..." /><br />
            <CogAnimation size={30} />
          {:else}
            <i><Tr s="Nothing found" /></i>
          {/if}
        {/key}
      {:else if article}
        <Article
          {article}
          {query}
          on:prev={(e) => nextArticle(-1)}
          on:next={(e) => nextArticle(1)}
        />
      {:else}
        <h2><Tr s="Pedia sections" /></h2>
        <p>
          {#each rul.sectionsOrder as section, i}
            {@html divider(i)}
            <a href={"##" + section.id}>{section.title}</a>
          {/each}
        </p>
        <h2><Tr s="Extra sections" /></h2>
        <p>
          {#each rul.typeSectionsOrder as section, i}
            {@html divider(i)}
            <a href={"##" + section.id}
              >{section.title}{tableSections.includes(section.id) ? "☰" : ""}</a
            >
          {/each}
        </p>
        <h2><Tr s="Mods" /></h2>
        <ul>
          {#each rul.mods as mod}
            <li>{mod.name} {mod.version}</li>
          {/each}
        </ul>
        {#if !packedData}
          <h2><Tr s="Export" /></h2>
          <Tr s="aboutexport" /><br />
          <button class="download"
            on:click={(e) => {
              useCache("wipe");
              location.reload();
            }}
            tooltip="tip_refresh"
          >
            ⭯
          </button>
          <Download title="Export all languages" />
          <Download
            title={rul.langName == "en-US"
              ? `Export English only`
              : `Export current (${rul.tr(rul.langName)}) and English only`}
            onlyCurrent={true}
          />
          <br />
        {/if}
        <h2><Tr s="About XPedia" /></h2>
        <Tr s="STR_ABOUT_XPEDIA" />
      {/if}
    </div>

    <div class="tooltip fadein" bind:this={tooltip}>Tooltip</div>
  {/key}
{/if}
